/** [Internal] A conversation between a user and the Linear AI assistant. Each conversation tracks the full thread state, context references (issues, projects, documents, etc.), and conversation parts (prompts, text responses, tool calls, widgets). Conversations can originate from direct chat, issue comments, Slack threads, Microsoft Teams, or automated workflows. */
export interface AiConversation {
  readonly archivedAt: string | null;
  readonly clientPlatform: "web" | "desktop" | "mobile" | null;
  readonly context: unknown;
  readonly createdAt: string;
  readonly diff: Diff | null;
  readonly document: Document | null;
  readonly evalLogId: string | null;
  readonly id: string;
  readonly initialSource:
    | "slack"
    | "microsoftTeams"
    | "mcp"
    | "directChat"
    | "entityChat"
    | "comment"
    | "pullRequestComment"
    | "workflow"
    | "onboarding"
    | "subAgent";
  readonly initiative: Initiative | null;
  readonly issue: Issue | null;
  readonly iterationId: string | null;
  readonly loopExecution: LoopExecution | null;
  readonly parts: ReadonlyArray<
    | AiConversationPromptPart
    | AiConversationTextPart
    | AiConversationReasoningPart
    | AiConversationEventPart
    | AiConversationErrorPart
    | AiConversationToolCallPart
    | AiConversationWidgetPart
    | AiConversationElicitationPart
    | AiConversationElicitationResponsePart
    | AiConversationAckPart
  > | null;
  readonly project: Project | null;
  readonly pullRequest: PullRequest | null;
  readonly readAt: string | null;
  readonly slugId: string;
  readonly status:
    | "active"
    | "complete"
    | "awaitingInput"
    | "error"
    | "pending"
    | "waiting";
  readonly summary: string | null;
  readonly updatedAt: string;
  readonly user: User | null;
  readonly userState: ReadonlyArray<AiConversationUserState>;
  readonly workflowCronJobDefinition: WorkflowCronJobDefinition | null;
  readonly workflowDefinition: WorkflowDefinition | null;
}

