/** A time-triggered automation workflow definition that executes on a recurring schedule. Cron job definitions are scoped to a team and contain a set of activities (actions) that run automatically according to the configured cron schedule, such as periodically assigning issues or sending notifications. */
export interface WorkflowCronJobDefinition {
  readonly activities: unknown;
  readonly archivedAt: string | null;
  readonly createdAt: string;
  readonly creator: User;
  readonly description: string | null;
  readonly enabled: boolean;
  readonly id: string;
  readonly name: string;
  readonly schedule: unknown;
  readonly sortOrder: string;
  readonly team: Team | null;
  readonly updatedAt: string;
}

/** An automation workflow definition that executes a set of activities when triggered by specific events. Workflows can be scoped to a team, project, cycle, label, custom view, initiative, or user context. They are triggered by entity changes (e.g., issue status change, new comment) and can include conditions that filter which events actually execute the workflow. Activities define the actions taken, such as updating issue properties, sending notifications, or posting to Slack. */
export interface WorkflowDefinition {
  readonly activationMode:
    | "conditionsStartedMatching"
    | "anyUpdate"
    | "watchedPropertyChanged"
    | "collectionChanged"
    | null;
  readonly activities: unknown;
  readonly applyToSubTeams: boolean;
  readonly archivedAt: string | null;
  readonly color: string | null;
  readonly conditions: unknown | null;
  readonly contextViewType:
    | "activeIssues"
    | "activeCycle"
    | "upcomingCycle"
    | "backlog"
    | "triage"
    | null;
  readonly createdAt: string;
  readonly creator: User;
  readonly customView: CustomView | null;
  readonly cycle: Cycle | null;
  readonly description: string | null;
  readonly editAccess:
    | "everyone"
    | "workspaceAdmins"
    | "teamOwners"
    | "owner"
    | null;
  readonly enabled: boolean;
  readonly groupName: string | null;
  readonly icon: string | null;
  readonly id: string;
  readonly initiative: Initiative | null;
  readonly intelligence: "auto" | "low" | "medium" | "high" | null;
  readonly label: IssueLabel | null;
  readonly lastExecutedAt: string | null;
  readonly lastUpdatedBy: User | null;
  readonly name: string;
  readonly owner: User | null;
  readonly project: Project | null;
  readonly restrictEditing: boolean;
  readonly runOnce: boolean;
  readonly schedule: unknown | null;
  readonly slugId: string;
  readonly sortOrder: string;
  readonly stats: unknown | null;
  readonly team: Team | null;
  readonly trigger:
    | "entityCreated"
    | "entityUpdated"
    | "entityCreatedOrUpdated"
    | "entityRemoved"
    | "entityUnarchived"
    | "cycleStarted"
    | "cycleEnded"
    | "commentAdded"
    | "commentResolved"
    | "reviewSubmitted"
    | "updatePosted"
    | "chatMessagePosted"
    | "chatReactionAdded"
    | "customerRequestAdded";
  readonly triggerConfig: unknown | null;
  readonly triggerType:
    | "issue"
    | "project"
    | "document"
    | "initiative"
    | "team"
    | "release"
    | "cycle"
    | "schedule"
    | "chat"
    | "pullRequest";
  readonly type:
    | "sla"
    | "automation"
    | "viewSubscription"
    | "triage"
    | "triageAutomation"
    | "release";
  readonly updatedAt: string;
  readonly user: User | null;
  readonly userContextViewType: "assigned" | null;
}

